from collections import deque
from pathlib import Path

def transform(grid):
    h,w=len(grid),len(grid[0])
    colors=sorted({v for row in grid for v in row if v})
    comps=[]
    for color in colors:
        seen=set()
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                            seen.add(p);q.append(p)
                comps.append((color,cells))
    bycolor={co:[cells for co2,cells in comps if co2==co] for co in colors}
    leftcolor=min(colors,key=lambda co:min(c for cells in bycolor[co] for _,c in cells))
    left_width=max(max(c for _,c in cells)-min(c for _,c in cells)+1 for cells in bycolor[leftcolor])
    starts={leftcolor:0}
    rightcolor=next(co for co in colors if co!=leftcolor)
    starts[rightcolor]=left_width+1
    out=[[0]*w for _ in range(h)]
    for co in colors:
        # Order from left to right by component centroid; left object at bottom.
        shapes=sorted(bycolor[co],key=lambda cells:sum(c for _,c in cells)/len(cells))
        # bottom-most x object goes at bottom; next one stacked above with a blank row
        bottom=h-1
        for cells in shapes:
            minr=min(r for r,c in cells); maxr=max(r for r,c in cells)
            minc=min(c for r,c in cells)
            top=bottom-(maxr-minr)
            for r,c in cells:
                out[top+r-minr][starts[co]+c-minc]=co
            bottom=top-2
    return out
